using System;
using System.Collections.Generic;
using AutoClicker.Models;

namespace AutoClicker.Utils
{
    /// <summary>
    /// UI localization. Strings are keyed by their English source text
    /// (gettext-style): T("Always on top") returns the translation for the
    /// active language, or the English text itself when no translation exists, so
    /// any untranslated string degrades gracefully to English rather than breaking.
    ///
    /// All controls built through UiFactory pass their text through T automatically,
    /// so adding a translation here localizes it everywhere without touching call
    /// sites. Language changes apply on restart.
    /// </summary>
    public static class Localization
    {
        private static Language _current = Language.English;

        /// <summary>
        /// The active language. Switching it clears the translation-coverage counters,
        /// which are per-language — otherwise Live debug would report misses collected
        /// under the previous language and blame the new one for them.
        /// </summary>
        public static Language Current
        {
            get => _current;
            set
            {
                if (_current == value)
                {
                    return;
                }
                _current = value;
                ResetCoverage();
            }
        }

        /// <summary>
        /// The .NET culture matching the current app language, used for formatting
        /// dates (weekday/month names) so charts and date labels follow the chosen
        /// language rather than the operating system locale.
        /// </summary>
        public static System.Globalization.CultureInfo DateCulture
        {
            get
            {
                try
                {
                    switch (Current)
                    {
                        case Language.Spanish: return System.Globalization.CultureInfo.GetCultureInfo("es");
                        case Language.French: return System.Globalization.CultureInfo.GetCultureInfo("fr");
                        case Language.German: return System.Globalization.CultureInfo.GetCultureInfo("de");
                        case Language.Italian: return System.Globalization.CultureInfo.GetCultureInfo("it");
                        case Language.Portuguese: return System.Globalization.CultureInfo.GetCultureInfo("pt");
                    }
                }
                catch { /* fall through to invariant if the culture isn't available */ }
                return System.Globalization.CultureInfo.InvariantCulture;
            }
        }

        public static IReadOnlyList<string> LanguageNames => new[]
        {
            "English", "Español", "Français", "Deutsch", "Italiano", "Português"
        };

        /// <summary>Returns the localized string for the English source text.</summary>
        public static string T(string english)
        {
            if (string.IsNullOrEmpty(english) || Current == Language.English)
            {
                return english;
            }

            Dictionary<string, string> table = TableFor(Current);
            if (table != null && table.TryGetValue(english, out string value))
            {
                _hits++;
                return value;
            }

            // Falling back to English is right — a missing phrase must never blank the
            // UI — but doing it SILENTLY meant an untranslated string could ship for
            // months without anyone noticing. Record the misses so Live debug can say
            // how complete the active language actually is, and name the offenders.
            RecordMiss(english);
            return english;
        }

        /// <summary>
        /// Translates a format string, then fills in the values: F("Delete macro '{0}'?", name).
        ///
        /// This is what makes a sentence containing a runtime value translatable at all.
        /// Built by concatenation — "Delete macro '" + name + "'?" — the finished string is
        /// different every time and can never match a dictionary key, so such messages
        /// stayed English no matter how complete the tables were. With the value moved to a
        /// placeholder, the key is stable AND the translator can move the value to wherever
        /// the target language needs it, which concatenation makes impossible.
        ///
        /// Never throws on a bad format: a message that arrives mangled is still worth more
        /// than an exception raised while trying to tell the user something.
        /// </summary>
        public static string F(string english, params object[] args)
        {
            string text = T(english);
            if (args == null || args.Length == 0) { return text; }
            try { return string.Format(text, args); }
            catch (FormatException)
            {
                // A translation with a malformed placeholder must not take the message
                // down with it — fall back to the English format, then to the raw text.
                try { return string.Format(english, args); }
                catch (FormatException) { return text; }
            }
        }

        private static int _hits;
        private static readonly HashSet<string> _misses = new HashSet<string>(StringComparer.Ordinal);

        private static void RecordMiss(string english)
        {
            try
            {
                // Ignore text that is ALREADY a translation. Several UI helpers
                // (UiFactory.Label/Button/Check/Group/Combo) translate their caption
                // themselves, and ~71 call sites also wrap the caption in T() before
                // passing it in. The second lookup is handed Spanish, finds nothing and
                // harmlessly returns it unchanged — the UI is correct — but counting
                // those as gaps reported ~180 phantom "untranslated" phrases and made
                // the coverage figure useless. A real gap is English that has no entry.
                if (IsAlreadyTranslated(english))
                {
                    _doubleTranslated++;
                    return;
                }

                lock (_misses)
                {
                    if (_misses.Count < 500)   // bounded: this is a diagnostic, not a leak
                    {
                        _misses.Add(english);
                    }
                }
            }
            catch { }
        }

        private static int _doubleTranslated;
        private static Language _reverseFor = Language.English;
        private static HashSet<string> _reverse;

        /// <summary>Number of lookups that were handed already-translated text.</summary>
        public static int DoubleTranslatedCount => _doubleTranslated;

        /// <summary>True when the text is a translation OUTPUT of the active language.</summary>
        private static bool IsAlreadyTranslated(string text)
        {
            Dictionary<string, string> table = TableFor(Current);
            if (table == null)
            {
                return false;
            }

            if (_reverse == null || _reverseFor != Current)
            {
                var set = new HashSet<string>(StringComparer.Ordinal);
                foreach (string v in table.Values)
                {
                    set.Add(v);
                }
                _reverse = set;
                _reverseFor = Current;
            }

            return _reverse.Contains(text);
        }

        /// <summary>Phrases translated so far this session.</summary>
        public static int TranslatedCount => _hits;

        /// <summary>Distinct phrases with no translation in the active language.</summary>
        public static int UntranslatedCount
        {
            get { lock (_misses) { return _misses.Count; } }
        }

        /// <summary>A few untranslated phrases, for the Live debug report.</summary>
        public static string SampleUntranslated(int max = 3)
        {
            lock (_misses)
            {
                if (_misses.Count == 0)
                {
                    return string.Empty;
                }
                var list = new List<string>();
                foreach (string s in _misses)
                {
                    list.Add(s.Length > 28 ? s.Substring(0, 27) + "…" : s);
                    if (list.Count >= max) { break; }
                }
                return string.Join(", ", list);
            }
        }

        /// <summary>Forgets recorded misses — used when the language changes.</summary>
        public static void ResetCoverage()
        {
            _hits = 0;
            _doubleTranslated = 0;
            _reverse = null;
            lock (_misses) { _misses.Clear(); }
        }

        /// <summary>
        /// Best-effort match of the user's Windows display language to one of the
        /// languages Tempo already ships. Returns English when there's no match.
        /// This lets Tempo come up in the user's language automatically without
        /// adding any new translations - it just uses the ones already built in.
        /// </summary>
        public static Models.Language DetectSystemLanguage()
        {
            try
            {
                string two = System.Globalization.CultureInfo.CurrentUICulture
                    .TwoLetterISOLanguageName.ToLowerInvariant();
                switch (two)
                {
                    case "es": return Models.Language.Spanish;
                    case "fr": return Models.Language.French;
                    case "de": return Models.Language.German;
                    case "it": return Models.Language.Italian;
                    case "pt": return Models.Language.Portuguese;
                    default: return Models.Language.English;
                }
            }
            catch
            {
                return Models.Language.English;
            }
        }

        private static Dictionary<string, string> TableFor(Language language)
        {
            switch (language)
            {
                case Language.Spanish: return Es;
                case Language.French: return Fr;
                case Language.German: return De;
                case Language.Italian: return It;
                case Language.Portuguese: return Pt;
                default: return null;
            }
        }

        // Merges the per-release "extra" translation blocks below into the main tables
        // once, at first use. Keeping new strings in their own small, clearly-labelled
        // dictionaries means a release's additions can be reviewed as a unit and never
        // risks a bad edit to the five large tables. A later duplicate key simply wins,
        // which is the intended "override" behaviour.
        static Localization()
        {
            Merge(Es, EsExtra);
            Merge(Fr, FrExtra);
            Merge(De, DeExtra);
            Merge(It, ItExtra);
            Merge(Pt, PtExtra);
        }

        private static void Merge(Dictionary<string, string> into, Dictionary<string, string> extra)
        {
            if (into == null || extra == null) { return; }
            foreach (var kv in extra) { into[kv.Key] = kv.Value; }
        }

