            ["Copied  ✓"] = "Copiado  ✓",
            ["Copy/Save include the stats above + the recent events."] = "Copiar/Guardar incluyen las estadísticas de arriba y los eventos recientes.",
            ["Couldn't copy to the clipboard — another app may be holding it.\n\nUse Save… instead.\n\n{0}"] = "No se pudo copiar al portapapeles: puede que otra aplicación lo esté ocupando.\n\nUsa Guardar… en su lugar.\n\n{0}",
            ["Save the live debug report"] = "Guardar el informe de depuración en vivo",
            ["Log files (*.log)|*.log|All files (*.*)|*.*"] = "Archivos de registro (*.log)|*.log|Todos los archivos (*.*)|*.*",
            // Legend chips — lower case on purpose, they label colour swatches.
            ["errors"] = "errores",
            ["warnings"] = "avisos",
            ["captions"] = "subtítulos",
            ["movement"] = "movimiento",
            ["audio"] = "audio",
            ["input"] = "entrada",
