            ["Rescan"] = "Volver a buscar",
            ["Using: {0}"] = "Usando: {0}",
            ["Tempo runs the script with your own Python and waits for it to finish. Held keys and buttons are released first, so nothing stays pressed while it runs."] = "Tempo ejecuta el script con tu propio Python y espera a que termine. Las teclas y botones mantenidos se sueltan antes, así que nada queda pulsado mientras se ejecuta.",
            ["Choose a Python script"] = "Elige un script de Python",
            ["Python script (*.py;*.pyw)|*.py;*.pyw|All files (*.*)|*.*"] = "Script de Python (*.py;*.pyw)|*.py;*.pyw|Todos los archivos (*.*)|*.*",
            ["Choose a .py file for this step."] = "Elige un archivo .py para este paso.",
            ["That file doesn't exist:\n\n{0}"] = "Ese archivo no existe:\n\n{0}",
            ["No Python interpreter found on this PC."] = "No se encontró ningún intérprete de Python en este PC.",
            ["Tempo could not find Python on this PC. Install it from python.org, then use Rescan in the script step."] = "Tempo no encontró Python en este PC. Instálalo desde python.org y luego usa Volver a buscar en el paso de script.",
            ["Python could not be started."] = "No se pudo iniciar Python.",
            ["The script file no longer exists:\n{0}"] = "El archivo del script ya no existe:\n{0}",
            ["The script exited with code {0}."] = "El script terminó con el código {0}.",
            ["The script was still running after {0} ms and was stopped."] = "El script seguía ejecutándose después de {0} ms y se detuvo.",
            ["The macro was stopped while the script was running."] = "La macro se detuvo mientras el script se estaba ejecutando.",
            ["… {0} more line(s) not shown."] = "… {0} línea(s) más no mostradas.",
            ["Script step failed: {0}"] = "Falló el paso de script: {0}",
            ["Script step failed: {0}\n{1}"] = "Falló el paso de script: {0}\n{1}",
            ["{0} script step(s) in \"{1}\" point at a file that isn't there:\n\n{2}\nOpen the macro editor and pick the file again, or delete those steps."] = "{0} paso(s) de script en \"{1}\" apuntan a un archivo que no existe:\n\n{2}\nAbre el editor de macros y vuelve a elegir el archivo, o elimina esos pasos.",
            ["'{0}' contains {1} step(s) that run a Python script:\n\n{2}\nScripts run as you, with your files and your network. Only keep this macro if you trust where it came from and you have read the script.\n\nImport it anyway?"] = "'{0}' contiene {1} paso(s) que ejecutan un script de Python:\n\n{2}\nLos scripts se ejecutan como tú, con tus archivos y tu red. Conserva esta macro solo si confías en su procedencia y has leído el script.\n\n¿Importarla de todos modos?",
            ["Tempo's speech models come from the whisper.cpp project on Hugging Face — the same place the \"Download model\" button uses. You only need this page for something Tempo doesn't list, such as a language-specific or fine-tuned model.\n\nOn that page:\n   •  Download any file named ggml-….bin  (ignore everything else)\n   •  \"q5\" / \"q8\" in the name means a smaller, quantised build — same hearing, about a third of the size and CPU\n   •  \".en\" means English-only; without it, the model handles any language\n   •  Bigger is more accurate but slower — large is roughly 3 GB\n\nThen save it into Tempo's models folder and it will be picked up automatically. You can also keep it anywhere you like and use \"Use a model file from anywhere\".\n\nOpen the page in your browser now?"] = "Los modelos de voz de Tempo vienen del proyecto whisper.cpp en Hugging Face, el mismo sitio que usa el botón \"Descargar modelo\". Solo necesitas esta página para algo que Tempo no incluya, como un modelo específico de un idioma o ajustado.\n\nEn esa página:\n   •  Descarga cualquier archivo llamado ggml-….bin  (ignora todo lo demás)\n   •  \"q5\" / \"q8\" en el nombre significa una versión cuantizada más pequeña: oye igual, con un tercio del tamaño y de la CPU\n   •  \".en\" significa solo inglés; sin eso, el modelo entiende cualquier idioma\n   •  Cuanto más grande, más preciso pero más lento: large ocupa unos 3 GB\n\nLuego guárdalo en la carpeta de modelos de Tempo y se detectará automáticamente. También puedes dejarlo donde quieras y usar \"Usar un archivo de modelo de cualquier sitio\".\n\n¿Abrir la página en tu navegador ahora?",
            ["That file could not be read as Tempo settings."] = "No se pudo leer ese archivo como ajustes de Tempo.",
            ["The update check took too long and was cancelled. Please check your connection and try again."] = "La comprobación de actualizaciones tardó demasiado y se canceló. Revisa tu conexión e inténtalo de nuevo.",
            ["The update failed its integrity check (checksum mismatch). Please try again, or use the download page."] = "La actualización no superó la comprobación de integridad (la suma no coincide). Inténtalo de nuevo o usa la página de descargas.",
            ["There are no macros to export."] = "No hay macros que exportar.",
            ["There are no other macros to merge in."] = "No hay otras macros que fusionar.",
            ["This macro has no play stats to reset."] = "Esta macro no tiene estadísticas de reproducción que restablecer.",
            ["This macro has no steps yet — record or edit it first."] = "Esta macro aún no tiene pasos: grábala o edítala primero.",
            ["Window position reset."] = "Posición de la ventana restablecida.",
            ["A macro is still being recorded.\n\nUpdating restarts Tempo, which discards the recording in progress.\n\nYes — discard it and update now\nNo — cancel the update so you can finish and save it"] = "Todavía se está grabando una macro.\n\nActualizar reinicia Tempo, lo que descarta la grabación en curso.\n\nSí: descartarla y actualizar ahora\nNo: cancelar la actualización para poder terminarla y guardarla",
            ["Also delete the Tempo program file itself?\n\nYes — remove everything, including Tempo.exe\nNo — remove data only and keep Tempo.exe\n\nTempo will close to finish removing files."] = "¿Eliminar también el propio archivo de programa de Tempo?\n\nSí: eliminar todo, incluido Tempo.exe\nNo: eliminar solo los datos y conservar Tempo.exe\n\nTempo se cerrará para terminar de eliminar los archivos.",
            ["Back up all your data first?\n\nYes — choose a folder; Tempo copies all profiles, macros, settings\n         and history there before uninstalling\nNo — uninstall without a backup"] = "¿Hacer primero una copia de seguridad de todos tus datos?\n\nSí: elige una carpeta; Tempo copiará allí todos los perfiles, macros, ajustes\n         e historial antes de desinstalar\nNo: desinstalar sin copia de seguridad",
            ["A macro with that name already exists."] = "Ya existe una macro con ese nombre.",
            ["Add at least one enabled point first."] = "Añade primero al menos un punto activado.",
            ["Clear the recent-sessions history?"] = "¿Borrar el historial de sesiones recientes?",
            ["Clicking is still running. Exit anyway?"] = "Los clics siguen en marcha. ¿Salir de todos modos?",
            ["Could not export settings."] = "No se pudieron exportar los ajustes.",
            ["Could not export the macro."] = "No se pudo exportar la macro.",
            ["Could not export the macros."] = "No se pudieron exportar las macros.",
            ["Could not import that file. It may not be a valid macro."] = "No se pudo importar ese archivo. Puede que no sea una macro válida.",
            ["Could not read that file as a macro collection."] = "No se pudo leer ese archivo como una colección de macros.",
            ["Could not start recording. The input hook failed to install."] = "No se pudo iniciar la grabación. No se pudo instalar el enganche de entrada.",
            ["Couldn't copy to the clipboard — it may be in use by another app."] = "No se pudo copiar al portapapeles: puede que otra aplicación lo esté usando.",
            ["No log file has been created yet."] = "Todavía no se ha creado ningún archivo de registro.",
            ["Remove all points?"] = "¿Eliminar todos los puntos?",
