            ["Select the macro to merge into first."] = "Selecciona primero la macro en la que fusionar.",
            ["Settings exported."] = "Ajustes exportados.",
            ["Settings imported."] = "Ajustes importados.",
            ["Statistics exported."] = "Estadísticas exportadas.",
            ["Statistics summary copied to the clipboard."] = "Resumen de estadísticas copiado al portapapeles.",
            ["Tempo couldn't restart automatically. Please reopen it to apply the new language."] = "Tempo no pudo reiniciarse automáticamente. Vuelve a abrirlo para aplicar el nuevo idioma.",
            ["Reset all lifetime totals (clicks, sessions, best CPS, runtime)?\nThis cannot be undone."] = "¿Restablecer todos los totales históricos (clics, sesiones, mejor CPS, tiempo de uso)?\nEsto no se puede deshacer.",
            ["Reset the current session's statistics?\n\nThis clears the session counters, peak CPS and the live charts. Your lifetime totals and saved history are not affected."] = "¿Restablecer las estadísticas de la sesión actual?\n\nEsto borra los contadores de la sesión, el CPS máximo y los gráficos en vivo. Tus totales históricos y el historial guardado no se ven afectados.",
            ["Tempo couldn't add itself to Windows startup — the registry write was blocked (this can happen on locked-down or work PCs). Startup launch is not active. You can try again, or add Tempo to startup manually."] = "Tempo no pudo añadirse al inicio de Windows: se bloqueó la escritura en el registro (puede ocurrir en equipos restringidos o de trabajo). El inicio automático no está activo. Puedes intentarlo de nuevo o añadir Tempo al inicio manualmente.",
            ["OK"] = "Aceptar",
            ["Yes"] = "Sí",
            ["No"] = "No",
            ["Tempo is already running"] = "Tempo ya se está ejecutando",
            ["Its window has been brought to the front."] = "Su ventana se ha traído al frente.",
            ["If you can't see it, look for the Tempo icon in the system tray — bottom-right, near the clock. You may need to click the ^ arrow first."] = "Si no la ves, busca el icono de Tempo en la bandeja del sistema, abajo a la derecha junto al reloj. Puede que tengas que pulsar antes la flecha ^.",
            ["Always on top: ON"] = "Siempre visible: ACTIVADO",
            ["Always on top: OFF"] = "Siempre visible: DESACTIVADO",
            ["Camera-relative movement ARMED — W/A/S/D are being re-mixed."] = "Movimiento relativo a la cámara ACTIVADO: se están remezclando W/A/S/D.",
            ["Camera-relative movement off."] = "Movimiento relativo a la cámara desactivado.",
            ["Camera-relative movement disarmed"] = "Movimiento relativo a la cámara desactivado",
            ["Minimised to tray."] = "Minimizado a la bandeja.",
            ["Running in the tray."] = "En ejecución en la bandeja.",
            ["Started with Windows — running in the tray."] = "Iniciado con Windows: en ejecución en la bandeja.",
            ["Tempo is running in the tray"] = "Tempo se está ejecutando en la bandeja",
            ["Tempo is still running"] = "Tempo sigue en ejecución",
            ["Tempo milestone reached!"] = "¡Hito de Tempo alcanzado!",
            ["Speech model changed"] = "Modelo de voz cambiado",
            ["Two caption engines are running"] = "Hay dos motores de subtítulos en marcha",
            ["Tempo Live Captions"] = "Subtítulos en directo de Tempo",
            ["Closing the window keeps Tempo in the system tray (bottom-right, near the clock) so hotkeys keep working. Click its icon to reopen, or right-click it to Exit. You can change this in Settings."] = "Al cerrar la ventana, Tempo se queda en la bandeja del sistema (abajo a la derecha, junto al reloj) para que las teclas rápidas sigan funcionando. Haz clic en su icono para volver a abrirlo, o clic derecho para Salir. Puedes cambiar esto en Ajustes.",
            ["Tempo started with Windows and is running in the system tray (bottom-right, near the clock). Click its icon to open the window."] = "Tempo se inició con Windows y se está ejecutando en la bandeja del sistema (abajo a la derecha, junto al reloj). Haz clic en su icono para abrir la ventana.",
            ["Tempo is still running in the system tray (bottom-right, near the clock). Click its icon to open the window. (Change this in Settings.)"] = "Tempo sigue en ejecución en la bandeja del sistema (abajo a la derecha, junto al reloj). Haz clic en su icono para abrir la ventana. (Puedes cambiarlo en Ajustes.)",
            ["Couldn't start Windows Live Captions automatically. Press Win+Ctrl+L once, or turn it on in Settings > Accessibility > Captions. The first time, Windows may ask to set it up."] = "No se pudieron iniciar automáticamente los subtítulos en directo de Windows. Pulsa Win+Ctrl+L una vez, o actívalos en Configuración > Accesibilidad > Subtítulos. La primera vez, Windows puede pedir configurarlos.",
            ["Discord may show you as playing the Steam game \"Tempo\" because this folder is named Tempo. Rename the folder (e.g. TempoClicker) or reinstall with install.cmd to stop that."] = "Discord puede mostrar que estás jugando al juego de Steam \"Tempo\" porque esta carpeta se llama Tempo. Cambia el nombre de la carpeta (por ejemplo, TempoClicker) o reinstala con install.cmd para evitarlo.",
            ["Heads-up: the \"Speaker 1/2\" caption labels are AI guesses from voice pitch and pauses — they make plenty of mistakes. Treat them as a reading aid; turn off in Settings → Live Captions."] = "Aviso: las etiquetas \"Hablante 1/2\" de los subtítulos son conjeturas de la IA a partir del tono de voz y las pausas, y se equivocan a menudo. Tómalas como una ayuda de lectura; desactívalas en Ajustes → Subtítulos en directo.",
            ["Move mode ON: drag the caption bars where you want them, then turn move mode off in the tray to lock them."] = "Modo mover ACTIVADO: arrastra las barras de subtítulos donde quieras y luego desactiva el modo mover desde la bandeja para fijarlas.",
            ["Windows Live Captions can't be read on this PC (its accessibility API isn't working), so Tempo switched to its own offline captions."] = "No se pueden leer los subtítulos en directo de Windows en este PC (su API de accesibilidad no funciona), así que Tempo cambió a sus propios subtítulos sin conexión.",

            ["settings ok"] = "ajustes correctos",
