            ["Merged {0} step(s) from '{1}' into '{2}'."] = "{0} étape(s) fusionnée(s) depuis « {1} » vers « {2} ».",
            ["No macros found in that file."] = "Aucune macro trouvée dans ce fichier.",
            ["Open the download page instead?"] = "Ouvrir plutôt la page de téléchargement ?",
            ["Profile '{0}' saved."] = "Profil « {0} » enregistré.",
            ["Tempo couldn't restart automatically. Please reopen it to apply {0}."] = "Tempo n'a pas pu redémarrer automatiquement. Rouvrez-le pour appliquer {0}.",
            ["That file couldn't be loaded as an image, so it wasn't applied.\n\n{0}"] = "Ce fichier n'a pas pu être chargé comme image, il n'a donc pas été appliqué.\n\n{0}",
            ["The download failed."] = "Le téléchargement a échoué.",
            ["The model download failed. You can try again, or use “Open models folder” to add it manually."] = "Le téléchargement du modèle a échoué. Réessayez ou utilisez “Ouvrir le dossier des modèles” pour l'ajouter manuellement.",
            ["The update check failed."] = "La vérification des mises à jour a échoué.",
            ["Uninstall Tempo?\n\nThis will permanently remove:\n   •  All profiles and saved macros\n   •  Your settings and session history\n   •  Downloaded speech models\n   •  The log file\n   •  The Windows start-up entry (if set)\n   •  Start Menu and Desktop shortcuts\n   •  Tempo's entry in Settings > Apps\n\nAll of that lives in:\n{0}\n\nThis cannot be undone. Continue?"] = "Désinstaller Tempo ?\n\nCela supprimera définitivement :\n   •  Tous les profils et macros enregistrées\n   •  Vos réglages et l'historique des sessions\n   •  Les modèles vocaux téléchargés\n   •  Le fichier journal\n   •  L'entrée de démarrage Windows (le cas échéant)\n   •  Les raccourcis du menu Démarrer et du Bureau\n   •  L'entrée de Tempo dans Paramètres > Applications\n\nTout cela se trouve dans :\n{0}\n\nCette action est irréversible. Continuer ?",
            ["Unlock maximum click speed?\n\nThis raises the speed slider far above the normal limit (up to {0} clicks/second).\n\nAt extreme speeds Tempo can:\n   •  use a lot of CPU and make the mouse hard to control,\n   •  be obviously automated — many games ban auto-clickers.\n\nWindows and the target app may not register every click above ~1000/s.\nUse the Anti-Freeze option on this tab to cap CPU if needed.\n\nEnable advanced speed?"] = "Débloquer la vitesse de clic maximale ?\n\nCela élève le curseur de vitesse bien au-dessus de la limite normale (jusqu'à {0} clics/seconde).\n\nÀ des vitesses extrêmes, Tempo peut :\n   •  consommer beaucoup de processeur et rendre la souris difficile à contrôler,\n   •  être manifestement automatisé — beaucoup de jeux interdisent les auto-clickers.\n\nWindows et l'application cible peuvent ne pas enregistrer chaque clic au-delà d'environ 1000/s.\nUtilisez l'option Anti-gel de cet onglet pour limiter le processeur si nécessaire.\n\nActiver la vitesse avancée ?",
            ["You're up to date.\n\nTempo {0} is the latest version."] = "Vous êtes à jour.\n\nTempo {0} est la dernière version.",
            ["{0} installed. Tempo's own captions are ready to use."] = "{0} installé. Les sous-titres intégrés de Tempo sont prêts à l'emploi.",
            ["{0} is already installed."] = "{0} est déjà installé.",

