            ["Accent"] = "Accent",
            ["CSV file (*.csv)|*.csv|All files (*.*)|*.*"] = "Fichier CSV (*.csv)|*.csv|Tous les fichiers (*.*)|*.*",
            ["Choose a Whisper speech model"] = "Choisir un modèle vocal Whisper",
            ["Choose a background image (GIF animates)"] = "Choisir une image de fond (les GIF s'animent)",
