            ["No points yet.\r\nUse “Add…” or “Quick Capture” to create one,\r\nthen tick its row to enable it."] = "Aucun point pour l'instant.\r\nUtilisez « Ajouter… » ou « Capture rapide » pour en créer un,\r\npuis cochez sa ligne pour l'activer.",
            ["Pick position on screen (otherwise use current cursor)"] = "Choisir la position à l'écran (sinon, le curseur actuel est utilisé)",
            ["Pin to the top of the list (favourite)"] = "Épingler en haut de la liste (favori)",
            ["Press the key you want Tempo to auto-press.\n(Esc to cancel)"] = "Appuyez sur la touche que Tempo doit presser automatiquement.\n(Échap pour annuler)",
            ["Quit Tempo"] = "Quitter Tempo",
            ["Reset to default logo"] = "Rétablir le logo par défaut",
            ["Restarting to apply changes…"] = "Redémarrage pour appliquer les modifications…",
            ["Save your recording"] = "Enregistrez votre capture",
            ["Send a bug report"] = "Envoyer un rapport de bogue",
            ["Speaker labels are AI guesses"] = "Les étiquettes de locuteur sont des suppositions de l'IA",
            ["SubRip subtitles (*.srt)|*.srt|WebVTT subtitles (*.vtt)|*.vtt"] = "Sous-titres SubRip (*.srt)|*.srt|Sous-titres WebVTT (*.vtt)|*.vtt",
            ["Tempo settings (*.json)|*.json|All files (*.*)|*.*"] = "Réglages Tempo (*.json)|*.json|Tous les fichiers (*.*)|*.*",
            ["Text file (*.txt)|*.txt"] = "Fichier texte (*.txt)|*.txt",
            ["The quick brown fox  ·  Aa Bb 123"] = "Portez ce vieux whisky  ·  Éé Çç 123",
            ["The “Speaker 1 / Speaker 2” labels come from on-device AI that listens to voice pitch and pauses. It makes plenty of mistakes:\n\n•  similar voices can get the same number\n•  one person can be split into two speakers\n•  music and cross-talk confuse it\n\nTreat the numbers as a reading aid, never as identification. You can turn them off any time in Settings → Live Captions."] = "Les étiquettes « Locuteur 1 / Locuteur 2 » proviennent d'une IA locale qui écoute la hauteur de la voix et les pauses. Elle se trompe souvent :\n\n•  des voix semblables peuvent recevoir le même numéro\n•  une même personne peut être scindée en deux locuteurs\n•  la musique et les conversations croisées la déroutent\n\nTraitez ces numéros comme une aide à la lecture, jamais comme une identification. Vous pouvez les désactiver à tout moment dans Paramètres → Sous-titres en direct.",
            ["Ticked fixes are applied when you press Fix selected. Nothing else is changed."] = "Les corrections cochées sont appliquées quand vous appuyez sur Corriger la sélection. Rien d'autre n'est modifié.",
            ["WHAT'S NEW"] = "NOUVEAUTÉS",
            ["Website"] = "Site web",
            ["Whisper model (*.bin)|*.bin|All files (*.*)|*.*"] = "Modèle Whisper (*.bin)|*.bin|Tous les fichiers (*.*)|*.*",
            ["•  Clicking — intervals, burst and hold, multi-point sequences, randomisation\n•  Macros — record, replay and edit input, saved into profiles\n•  Live captions — offline speech-to-text for any sound on this PC, on the processor or your graphics card, in 90+ languages\n•  Notifications — Tempo's own, plus a mirror of Windows' own\n•  Global hotkeys, themes, live statistics and a CPS test"] = "•  Clics — intervalles, rafales et maintien, séquences multipoints, aléatoire\n•  Macros — enregistrez, rejouez et modifiez la saisie, sauvegardées dans des profils\n•  Sous-titres en direct — reconnaissance vocale hors ligne pour tout son de ce PC, sur le processeur ou la carte graphique, en plus de 90 langues\n•  Notifications — celles de Tempo, plus un miroir de celles de Windows\n•  Raccourcis globaux, thèmes, statistiques en direct et un test de CPS",
            ["● Unsaved changes — click Save"] = "● Modifications non enregistrées — cliquez sur Enregistrer",
            ["● Unsaved changes — click Save Keybinds"] = "● Modifications non enregistrées — cliquez sur Enregistrer les raccourcis",

