            ["Rescan"] = "Rechercher",
            ["Using: {0}"] = "Utilise : {0}",
            ["Tempo runs the script with your own Python and waits for it to finish. Held keys and buttons are released first, so nothing stays pressed while it runs."] = "Tempo exécute le script avec votre propre Python et attend qu'il se termine. Les touches et boutons maintenus sont relâchés avant, donc rien ne reste enfoncé pendant son exécution.",
            ["Choose a Python script"] = "Choisir un script Python",
            ["Python script (*.py;*.pyw)|*.py;*.pyw|All files (*.*)|*.*"] = "Script Python (*.py;*.pyw)|*.py;*.pyw|Tous les fichiers (*.*)|*.*",
            ["Choose a .py file for this step."] = "Choisissez un fichier .py pour cette étape.",
            ["That file doesn't exist:\n\n{0}"] = "Ce fichier n'existe pas :\n\n{0}",
            ["No Python interpreter found on this PC."] = "Aucun interpréteur Python trouvé sur ce PC.",
            ["Tempo could not find Python on this PC. Install it from python.org, then use Rescan in the script step."] = "Tempo n'a pas trouvé Python sur ce PC. Installez-le depuis python.org, puis utilisez Rechercher dans l'étape de script.",
            ["Python could not be started."] = "Python n'a pas pu être démarré.",
            ["The script file no longer exists:\n{0}"] = "Le fichier du script n'existe plus :\n{0}",
            ["The script exited with code {0}."] = "Le script s'est terminé avec le code {0}.",
            ["The script was still running after {0} ms and was stopped."] = "Le script tournait encore après {0} ms et a été arrêté.",
            ["The macro was stopped while the script was running."] = "La macro a été arrêtée pendant l'exécution du script.",
            ["… {0} more line(s) not shown."] = "… {0} ligne(s) de plus non affichées.",
            ["Script step failed: {0}"] = "Échec de l'étape de script : {0}",
            ["Script step failed: {0}\n{1}"] = "Échec de l'étape de script : {0}\n{1}",
            ["{0} script step(s) in \"{1}\" point at a file that isn't there:\n\n{2}\nOpen the macro editor and pick the file again, or delete those steps."] = "{0} étape(s) de script dans « {1} » pointent vers un fichier absent :\n\n{2}\nOuvrez l'éditeur de macros et choisissez à nouveau le fichier, ou supprimez ces étapes.",
            ["'{0}' contains {1} step(s) that run a Python script:\n\n{2}\nScripts run as you, with your files and your network. Only keep this macro if you trust where it came from and you have read the script.\n\nImport it anyway?"] = "« {0} » contient {1} étape(s) qui exécutent un script Python :\n\n{2}\nLes scripts s'exécutent en votre nom, avec vos fichiers et votre réseau. Ne conservez cette macro que si vous avez confiance en sa provenance et que vous avez lu le script.\n\nL'importer quand même ?",
            ["Tempo's speech models come from the whisper.cpp project on Hugging Face — the same place the \"Download model\" button uses. You only need this page for something Tempo doesn't list, such as a language-specific or fine-tuned model.\n\nOn that page:\n   •  Download any file named ggml-….bin  (ignore everything else)\n   •  \"q5\" / \"q8\" in the name means a smaller, quantised build — same hearing, about a third of the size and CPU\n   •  \".en\" means English-only; without it, the model handles any language\n   •  Bigger is more accurate but slower — large is roughly 3 GB\n\nThen save it into Tempo's models folder and it will be picked up automatically. You can also keep it anywhere you like and use \"Use a model file from anywhere\".\n\nOpen the page in your browser now?"] = "Les modèles vocaux de Tempo proviennent du projet whisper.cpp sur Hugging Face, la même source que le bouton \"Télécharger le modèle\". Vous n'avez besoin de cette page que pour un modèle que Tempo ne propose pas, par exemple propre à une langue ou affiné.\n\nSur cette page :\n   •  Téléchargez un fichier nommé ggml-….bin  (ignorez tout le reste)\n   •  \"q5\" / \"q8\" indique une version quantifiée plus petite — même qualité d'écoute, environ un tiers de la taille et du processeur\n   •  \".en\" signifie anglais uniquement ; sans cela, le modèle gère toutes les langues\n   •  Plus il est grand, plus il est précis mais lent — large fait environ 3 Go\n\nEnregistrez-le ensuite dans le dossier des modèles de Tempo et il sera détecté automatiquement. Vous pouvez aussi le garder où vous voulez et utiliser \"Utiliser un fichier de modèle depuis n'importe où\".\n\nOuvrir la page dans votre navigateur maintenant ?",
            ["That file could not be read as Tempo settings."] = "Ce fichier n'a pas pu être lu comme des réglages Tempo.",
            ["The update check took too long and was cancelled. Please check your connection and try again."] = "La vérification des mises à jour a pris trop de temps et a été annulée. Vérifiez votre connexion et réessayez.",
            ["The update failed its integrity check (checksum mismatch). Please try again, or use the download page."] = "La mise à jour a échoué au contrôle d'intégrité (somme de contrôle différente). Réessayez ou utilisez la page de téléchargement.",
            ["There are no macros to export."] = "Il n'y a aucune macro à exporter.",
            ["There are no other macros to merge in."] = "Il n'y a aucune autre macro à fusionner.",
            ["This macro has no play stats to reset."] = "Cette macro n'a aucune statistique de lecture à réinitialiser.",
            ["This macro has no steps yet — record or edit it first."] = "Cette macro n'a pas encore d'étapes — enregistrez-la ou modifiez-la d'abord.",
            ["Window position reset."] = "Position de la fenêtre réinitialisée.",
            ["A macro is still being recorded.\n\nUpdating restarts Tempo, which discards the recording in progress.\n\nYes — discard it and update now\nNo — cancel the update so you can finish and save it"] = "Une macro est encore en cours d'enregistrement.\n\nLa mise à jour redémarre Tempo, ce qui abandonne l'enregistrement en cours.\n\nOui — l'abandonner et mettre à jour maintenant\nNon — annuler la mise à jour pour pouvoir la terminer et l'enregistrer",
            ["Also delete the Tempo program file itself?\n\nYes — remove everything, including Tempo.exe\nNo — remove data only and keep Tempo.exe\n\nTempo will close to finish removing files."] = "Supprimer aussi le fichier programme de Tempo lui-même ?\n\nOui — tout supprimer, y compris Tempo.exe\nNon — supprimer seulement les données et conserver Tempo.exe\n\nTempo se fermera pour terminer la suppression des fichiers.",
            ["Back up all your data first?\n\nYes — choose a folder; Tempo copies all profiles, macros, settings\n         and history there before uninstalling\nNo — uninstall without a backup"] = "Sauvegarder d'abord toutes vos données ?\n\nOui — choisissez un dossier ; Tempo y copie tous les profils, macros, réglages\n         et l'historique avant la désinstallation\nNon — désinstaller sans sauvegarde",
            ["A macro with that name already exists."] = "Une macro portant ce nom existe déjà.",
            ["Add at least one enabled point first."] = "Ajoutez d'abord au moins un point activé.",
            ["Clear the recent-sessions history?"] = "Effacer l'historique des sessions récentes ?",
            ["Clicking is still running. Exit anyway?"] = "Le clic est toujours en cours. Quitter quand même ?",
            ["Could not export settings."] = "Impossible d'exporter les réglages.",
            ["Could not export the macro."] = "Impossible d'exporter la macro.",
            ["Could not export the macros."] = "Impossible d'exporter les macros.",
            ["Could not import that file. It may not be a valid macro."] = "Impossible d'importer ce fichier. Ce n'est peut-être pas une macro valide.",
            ["Could not read that file as a macro collection."] = "Impossible de lire ce fichier comme une collection de macros.",
            ["Could not start recording. The input hook failed to install."] = "Impossible de démarrer l'enregistrement. Le hook d'entrée n'a pas pu être installé.",
