            ["Copy/Save include the stats above + the recent events."] = "Kopieren/Speichern enthalten die Statistik oben und die letzten Ereignisse.",
            ["Couldn't copy to the clipboard — another app may be holding it.\n\nUse Save… instead.\n\n{0}"] = "Kopieren in die Zwischenablage nicht möglich — womöglich hält sie gerade eine andere Anwendung.\n\nNutze stattdessen Speichern….\n\n{0}",
            ["Save the live debug report"] = "Live-Diagnosebericht speichern",
