            ["system"] = "System",
            ["trace"] = "Trace",
            ["GitHub has no release matching this version number, so nothing outside this PC can confirm the file. That is normal for a build you made yourself — but if you downloaded it, get it from the official releases page instead."] = "Auf GitHub gibt es keine Veröffentlichung mit dieser Versionsnummer, also kann nichts außerhalb dieses PCs die Datei bestätigen. Bei einem selbst gebauten Build ist das normal — wenn du sie aber heruntergeladen hast, hole sie von der offiziellen Releases-Seite.",
            ["This copy does not match the release published for its version number. Either it was altered after download, or it did not come from the official releases page. Reinstall from there to be sure."] = "Diese Kopie stimmt nicht mit der für ihre Versionsnummer veröffentlichten Fassung überein. Entweder wurde sie nach dem Download verändert, oder sie stammt nicht von der offiziellen Releases-Seite. Installiere von dort neu, um sicherzugehen.",
            ["This version was never published"] = "Diese Version wurde nie veröffentlicht",
            ["⚠ No release with this version number exists on GitHub, so nothing outside this PC can confirm the file. Normal for a build you made yourself."] = "⚠ Auf GitHub existiert keine Veröffentlichung mit dieser Versionsnummer, also kann nichts außerhalb dieses PCs die Datei bestätigen. Bei einem selbst gebauten Build ist das normal.",
            ["✓ Verified against the release published on GitHub."] = "✓ Gegen die auf GitHub veröffentlichte Fassung geprüft.",
            ["✗ This copy does not match the release published for its version number. If you did not replace it yourself, reinstall from the official download."] = "✗ Diese Kopie stimmt nicht mit der für ihre Versionsnummer veröffentlichten Fassung überein. Wenn du sie nicht selbst ersetzt hast, installiere vom offiziellen Download neu.",
            ["Check now"] = "Jetzt prüfen",
            ["Check that Tempo hasn't been tampered with"] = "Prüfen, ob Tempo verändert wurde",
            ["Trust this copy"] = "Kopie vertrauen",
            ["Could not be checked right now."] = "Konnte gerade nicht geprüft werden.",
            ["Not checked yet."] = "Noch nicht geprüft.",
            ["Off — Tempo will not notice if its program file is replaced."] = "Aus — Tempo merkt nicht, wenn seine Programmdatei ersetzt wird.",
            ["Part of Tempo.exe is unreadable. This usually follows a crash or a power cut during an update. Reinstalling from the official download fixes it."] = "Ein Teil von Tempo.exe ist unlesbar. Das folgt meist auf einen Absturz oder einen Stromausfall während eines Updates. Eine Neuinstallation vom offiziellen Download behebt es.",
            ["Record this copy of Tempo.exe as the one you trust?\n\nOnly do this if you know why the file changed — for example you installed a build yourself. If you did not change it, do not accept it: reinstall from the official download instead."] = "Diese Kopie von Tempo.exe als vertrauenswürdig speichern?\n\nNur tun, wenn du weißt, warum sich die Datei geändert hat — etwa weil du selbst einen Build installiert hast. Wenn du sie nicht geändert hast, akzeptiere sie nicht: installiere stattdessen vom offiziellen Download neu.",
            ["Tempo has been modified"] = "Tempo wurde verändert",
            ["Tempo's program file is damaged"] = "Tempos Programmdatei ist beschädigt",
            ["Tempo.exe is not the file that was installed, and the version number has not changed. If you did not replace it yourself, reinstall from the official download."] = "Tempo.exe ist nicht die Datei, die installiert wurde, und die Versionsnummer hat sich nicht geändert. Wenn du sie nicht selbst ersetzt hast, installiere vom offiziellen Download neu.",
            ["This copy was packaged by someone else. If you did not build it yourself, replace it with the official download."] = "Diese Kopie wurde von jemand anderem gepackt. Wenn du sie nicht selbst gebaut hast, ersetze sie durch den offiziellen Download.",
            ["This is not an official Tempo build"] = "Das ist kein offizieller Tempo-Build",
            ["✓ Tempo.exe is the file that was installed."] = "✓ Tempo.exe ist die Datei, die installiert wurde.",
            ["✗ Tempo.exe has changed since it was installed. If you did not replace it yourself, reinstall from the official download."] = "✗ Tempo.exe hat sich seit der Installation geändert. Wenn du sie nicht selbst ersetzt hast, installiere vom offiziellen Download neu.",
            ["✗ Tempo.exe is damaged — part of it is unreadable. Reinstalling fixes it."] = "✗ Tempo.exe ist beschädigt — ein Teil ist unlesbar. Neu installieren behebt es.",
            ["✗ This copy was packaged by someone else, not the official Tempo build."] = "✗ Diese Kopie wurde von jemand anderem gepackt, nicht der offizielle Tempo-Build.",
            ["This report is too long for your email app to carry — it would arrive cut off part-way through, most likely losing the activity log at the end.\n\nCopy it to the clipboard instead? You can paste the whole thing into a new email."] = "Dieser Bericht ist zu lang für deine E-Mail-App — er käme mittendrin abgeschnitten an und würde höchstwahrscheinlich das Aktivitätsprotokoll am Ende verlieren.\n\nStattdessen in die Zwischenablage kopieren? Du kannst ihn dann vollständig in eine neue E-Mail einfügen.",
            ["Also include Tempo's recent activity log"] = "Auch Tempos jüngstes Aktivitätsprotokoll einschließen",
            ["Helps a lot, but may mention files you have opened in Tempo — it is added to the text above so you can read it first."] = "Hilft sehr, kann aber Dateien nennen, die du in Tempo geöffnet hast — es wird oben an den Text angehängt, damit du es vorher lesen kannst.",
            ["How would you like to send it?"] = "Wie möchtest du ihn senden?",
            ["Nothing is sent until you choose a way to send it below. Your Windows account name, PC name and personal folders are removed automatically — and this is the whole report, so you can edit or delete anything else before it goes."] = "Es wird nichts gesendet, bis du unten einen Weg zum Senden wählst. Dein Windows-Kontoname, der PC-Name und deine persönlichen Ordner werden automatisch entfernt — und dies ist der vollständige Bericht, du kannst also alles Weitere ändern oder löschen, bevor er rausgeht.",
            ["Privacy: this includes only Tempo's version, your Windows version and the technical error — never your clicks, settings or files. Your Windows account name and PC name are removed, from the subject line as well as the text. Nothing is sent until you submit. You can edit the text below first."] = "Datenschutz: Enthalten sind nur Tempos Version, deine Windows-Version und der technische Fehler — nie deine Klicks, Einstellungen oder Dateien. Dein Windows-Kontoname und der PC-Name werden entfernt, aus der Betreffzeile ebenso wie aus dem Text. Es wird nichts gesendet, bis du absendest. Du kannst den Text unten vorher bearbeiten.",
            ["There is no activity log to include yet."] = "Es gibt noch kein Aktivitätsprotokoll zum Einschließen.",
            ["{0}   ·  last used"] = "{0}   ·  zuletzt verwendet",
