            ["Rescan"] = "Neu suchen",
            ["Using: {0}"] = "Verwendet: {0}",
            ["Tempo runs the script with your own Python and waits for it to finish. Held keys and buttons are released first, so nothing stays pressed while it runs."] = "Tempo führt das Skript mit deinem eigenen Python aus und wartet, bis es fertig ist. Gehaltene Tasten und Maustasten werden vorher losgelassen, damit während der Ausführung nichts gedrückt bleibt.",
            ["Choose a Python script"] = "Ein Python-Skript wählen",
            ["Python script (*.py;*.pyw)|*.py;*.pyw|All files (*.*)|*.*"] = "Python-Skript (*.py;*.pyw)|*.py;*.pyw|Alle Dateien (*.*)|*.*",
            ["Choose a .py file for this step."] = "Wähle eine .py-Datei für diesen Schritt.",
            ["That file doesn't exist:\n\n{0}"] = "Diese Datei existiert nicht:\n\n{0}",
            ["No Python interpreter found on this PC."] = "Kein Python-Interpreter auf diesem PC gefunden.",
            ["Tempo could not find Python on this PC. Install it from python.org, then use Rescan in the script step."] = "Tempo hat auf diesem PC kein Python gefunden. Installiere es von python.org und nutze dann im Skriptschritt „Neu suchen“.",
            ["Python could not be started."] = "Python konnte nicht gestartet werden.",
            ["The script file no longer exists:\n{0}"] = "Die Skriptdatei existiert nicht mehr:\n{0}",
            ["The script exited with code {0}."] = "Das Skript endete mit Code {0}.",
            ["The script was still running after {0} ms and was stopped."] = "Das Skript lief nach {0} ms noch und wurde beendet.",
            ["The macro was stopped while the script was running."] = "Das Makro wurde angehalten, während das Skript lief.",
            ["… {0} more line(s) not shown."] = "… {0} weitere Zeile(n) nicht angezeigt.",
            ["Script step failed: {0}"] = "Skriptschritt fehlgeschlagen: {0}",
            ["Script step failed: {0}\n{1}"] = "Skriptschritt fehlgeschlagen: {0}\n{1}",
            ["{0} script step(s) in \"{1}\" point at a file that isn't there:\n\n{2}\nOpen the macro editor and pick the file again, or delete those steps."] = "{0} Skriptschritt(e) in „{1}“ zeigen auf eine Datei, die es nicht gibt:\n\n{2}\nÖffne den Makro-Editor und wähle die Datei erneut, oder lösche diese Schritte.",
            ["'{0}' contains {1} step(s) that run a Python script:\n\n{2}\nScripts run as you, with your files and your network. Only keep this macro if you trust where it came from and you have read the script.\n\nImport it anyway?"] = "„{0}“ enthält {1} Schritt(e), die ein Python-Skript ausführen:\n\n{2}\nSkripte laufen als du, mit deinen Dateien und deinem Netzwerk. Behalte dieses Makro nur, wenn du der Quelle vertraust und das Skript gelesen hast.\n\nTrotzdem importieren?",
            ["Tempo's speech models come from the whisper.cpp project on Hugging Face — the same place the \"Download model\" button uses. You only need this page for something Tempo doesn't list, such as a language-specific or fine-tuned model.\n\nOn that page:\n   •  Download any file named ggml-….bin  (ignore everything else)\n   •  \"q5\" / \"q8\" in the name means a smaller, quantised build — same hearing, about a third of the size and CPU\n   •  \".en\" means English-only; without it, the model handles any language\n   •  Bigger is more accurate but slower — large is roughly 3 GB\n\nThen save it into Tempo's models folder and it will be picked up automatically. You can also keep it anywhere you like and use \"Use a model file from anywhere\".\n\nOpen the page in your browser now?"] = "Tempos Sprachmodelle stammen aus dem whisper.cpp-Projekt auf Hugging Face — derselben Quelle, die auch die Schaltfläche \"Modell herunterladen\" nutzt. Diese Seite brauchst du nur für etwas, das Tempo nicht auflistet, etwa ein sprachspezifisches oder feinabgestimmtes Modell.\n\nAuf dieser Seite:\n   •  Lade eine Datei namens ggml-….bin herunter  (alles andere ignorieren)\n   •  \"q5\" / \"q8\" im Namen bedeutet eine kleinere, quantisierte Variante — gleiches Hörvermögen, etwa ein Drittel der Größe und CPU-Last\n   •  \".en\" bedeutet nur Englisch; ohne das versteht das Modell jede Sprache\n   •  Größer ist genauer, aber langsamer — large ist rund 3 GB\n\nSpeichere sie dann in Tempos Modellordner, und sie wird automatisch erkannt. Du kannst sie auch behalten, wo du willst, und \"Eine Modelldatei von überall verwenden\" nutzen.\n\nDie Seite jetzt im Browser öffnen?",
            ["That file could not be read as Tempo settings."] = "Diese Datei konnte nicht als Tempo-Einstellungen gelesen werden.",
            ["The update check took too long and was cancelled. Please check your connection and try again."] = "Die Update-Prüfung hat zu lange gedauert und wurde abgebrochen. Prüfe deine Verbindung und versuche es erneut.",
            ["The update failed its integrity check (checksum mismatch). Please try again, or use the download page."] = "Das Update hat die Integritätsprüfung nicht bestanden (Prüfsumme stimmt nicht). Versuche es erneut oder nutze die Download-Seite.",
            ["There are no macros to export."] = "Es gibt keine Makros zum Exportieren.",
            ["There are no other macros to merge in."] = "Es gibt keine weiteren Makros zum Zusammenführen.",
            ["This macro has no play stats to reset."] = "Dieses Makro hat keine Wiedergabestatistik zum Zurücksetzen.",
            ["This macro has no steps yet — record or edit it first."] = "Dieses Makro hat noch keine Schritte – nimm es zuerst auf oder bearbeite es.",
            ["Window position reset."] = "Fensterposition zurückgesetzt.",
            ["A macro is still being recorded.\n\nUpdating restarts Tempo, which discards the recording in progress.\n\nYes — discard it and update now\nNo — cancel the update so you can finish and save it"] = "Es wird noch ein Makro aufgezeichnet.\n\nDas Update startet Tempo neu und verwirft die laufende Aufzeichnung.\n\nJa – verwerfen und jetzt aktualisieren\nNein – Update abbrechen, damit du sie beenden und speichern kannst",
            ["Also delete the Tempo program file itself?\n\nYes — remove everything, including Tempo.exe\nNo — remove data only and keep Tempo.exe\n\nTempo will close to finish removing files."] = "Auch die Programmdatei von Tempo selbst löschen?\n\nJa – alles entfernen, einschließlich Tempo.exe\nNein – nur die Daten entfernen und Tempo.exe behalten\n\nTempo wird geschlossen, um das Entfernen abzuschließen.",
            ["Back up all your data first?\n\nYes — choose a folder; Tempo copies all profiles, macros, settings\n         and history there before uninstalling\nNo — uninstall without a backup"] = "Zuerst alle deine Daten sichern?\n\nJa – wähle einen Ordner; Tempo kopiert alle Profile, Makros, Einstellungen\n         und den Verlauf dorthin, bevor deinstalliert wird\nNein – ohne Sicherung deinstallieren",
            ["A macro with that name already exists."] = "Ein Makro mit diesem Namen existiert bereits.",
            ["Add at least one enabled point first."] = "Füge zuerst mindestens einen aktivierten Punkt hinzu.",
            ["Clear the recent-sessions history?"] = "Den Verlauf der letzten Sitzungen löschen?",
            ["Clicking is still running. Exit anyway?"] = "Das Klicken läuft noch. Trotzdem beenden?",
            ["Could not export settings."] = "Die Einstellungen konnten nicht exportiert werden.",
            ["Could not export the macro."] = "Das Makro konnte nicht exportiert werden.",
            ["Could not export the macros."] = "Die Makros konnten nicht exportiert werden.",
            ["Could not import that file. It may not be a valid macro."] = "Diese Datei konnte nicht importiert werden. Sie ist möglicherweise kein gültiges Makro.",
            ["Could not read that file as a macro collection."] = "Diese Datei konnte nicht als Makrosammlung gelesen werden.",
            ["Could not start recording. The input hook failed to install."] = "Die Aufzeichnung konnte nicht gestartet werden. Der Eingabe-Hook ließ sich nicht installieren.",
            ["Couldn't copy to the clipboard — it may be in use by another app."] = "Kopieren in die Zwischenablage fehlgeschlagen – eine andere App verwendet sie möglicherweise.",
            ["No log file has been created yet."] = "Es wurde noch keine Protokolldatei erstellt.",
            ["Remove all points?"] = "Alle Punkte entfernen?",
            ["Replace your current settings and keybinds with the imported ones?"] = "Deine aktuellen Einstellungen und Tastenkürzel durch die importierten ersetzen?",
            ["Reset all keybinds to their defaults?"] = "Alle Tastenkürzel auf die Standardwerte zurücksetzen?",
            ["Reset all settings to their defaults?"] = "Alle Einstellungen auf die Standardwerte zurücksetzen?",
            ["Select a delay step to edit its duration."] = "Wähle einen Warteschritt, um seine Dauer zu bearbeiten.",
            ["Select a macro first."] = "Wähle zuerst ein Makro.",
