            ["Select a macro to export first."] = "Wähle zuerst ein Makro zum Exportieren.",
            ["Select a macro to pin first."] = "Wähle zuerst ein Makro zum Anheften.",
            ["Select a macro to play first."] = "Wähle zuerst ein Makro zum Abspielen.",
            ["Select a move or click step to edit its position."] = "Wähle einen Bewegungs- oder Klickschritt, um seine Position zu bearbeiten.",
            ["Select the macro to merge into first."] = "Wähle zuerst das Makro, in das zusammengeführt werden soll.",
            ["Settings exported."] = "Einstellungen exportiert.",
            ["Settings imported."] = "Einstellungen importiert.",
            ["Statistics exported."] = "Statistiken exportiert.",
            ["Statistics summary copied to the clipboard."] = "Statistik-Zusammenfassung in die Zwischenablage kopiert.",
            ["Tempo couldn't restart automatically. Please reopen it to apply the new language."] = "Tempo konnte nicht automatisch neu starten. Öffne es erneut, um die neue Sprache zu übernehmen.",
            ["Reset all lifetime totals (clicks, sessions, best CPS, runtime)?\nThis cannot be undone."] = "Alle Gesamtwerte zurücksetzen (Klicks, Sitzungen, bester CPS, Laufzeit)?\nDies kann nicht rückgängig gemacht werden.",
            ["Reset the current session's statistics?\n\nThis clears the session counters, peak CPS and the live charts. Your lifetime totals and saved history are not affected."] = "Die Statistiken der aktuellen Sitzung zurücksetzen?\n\nDas löscht die Sitzungszähler, den Spitzen-CPS und die Live-Diagramme. Deine Gesamtwerte und der gespeicherte Verlauf bleiben unberührt.",
            ["Tempo couldn't add itself to Windows startup — the registry write was blocked (this can happen on locked-down or work PCs). Startup launch is not active. You can try again, or add Tempo to startup manually."] = "Tempo konnte sich nicht zum Windows-Autostart hinzufügen – der Registry-Schreibvorgang wurde blockiert (das kommt auf gesperrten oder Firmen-PCs vor). Der Start mit Windows ist nicht aktiv. Du kannst es erneut versuchen oder Tempo manuell zum Autostart hinzufügen.",
            ["OK"] = "OK",
            ["Tempo is already running"] = "Tempo läuft bereits",
            ["Yes"] = "Ja",
            ["No"] = "Nein",
            ["Its window has been brought to the front."] = "Sein Fenster wurde in den Vordergrund geholt.",
            ["If you can't see it, look for the Tempo icon in the system tray — bottom-right, near the clock. You may need to click the ^ arrow first."] = "Falls du es nicht siehst, schau nach dem Tempo-Symbol im Infobereich unten rechts neben der Uhr. Eventuell musst du zuerst auf den Pfeil ^ klicken.",
            ["Always on top: ON"] = "Immer im Vordergrund: EIN",
            ["Always on top: OFF"] = "Immer im Vordergrund: AUS",
            ["Camera-relative movement ARMED — W/A/S/D are being re-mixed."] = "Kamerarelative Bewegung AKTIV – W/A/S/D werden neu gemischt.",
            ["Camera-relative movement off."] = "Kamerarelative Bewegung aus.",
            ["Camera-relative movement disarmed"] = "Kamerarelative Bewegung deaktiviert",
            ["Minimised to tray."] = "In den Infobereich minimiert.",
            ["Running in the tray."] = "Läuft im Infobereich.",
            ["Started with Windows — running in the tray."] = "Mit Windows gestartet – läuft im Infobereich.",
            ["Tempo is running in the tray"] = "Tempo läuft im Infobereich",
            ["Tempo is still running"] = "Tempo läuft weiterhin",
            ["Tempo milestone reached!"] = "Tempo-Meilenstein erreicht!",
            ["Speech model changed"] = "Sprachmodell geändert",
            ["Two caption engines are running"] = "Zwei Untertitel-Engines laufen",
            ["Tempo Live Captions"] = "Tempo-Live-Untertitel",
            ["Closing the window keeps Tempo in the system tray (bottom-right, near the clock) so hotkeys keep working. Click its icon to reopen, or right-click it to Exit. You can change this in Settings."] = "Beim Schließen des Fensters bleibt Tempo im Infobereich (unten rechts, neben der Uhr), damit die Tastenkürzel weiter funktionieren. Klicke auf das Symbol, um es wieder zu öffnen, oder mit der rechten Maustaste für Beenden. Das lässt sich in den Einstellungen ändern.",
            ["Tempo started with Windows and is running in the system tray (bottom-right, near the clock). Click its icon to open the window."] = "Tempo ist mit Windows gestartet und läuft im Infobereich (unten rechts, neben der Uhr). Klicke auf das Symbol, um das Fenster zu öffnen.",
            ["Tempo is still running in the system tray (bottom-right, near the clock). Click its icon to open the window. (Change this in Settings.)"] = "Tempo läuft weiterhin im Infobereich (unten rechts, neben der Uhr). Klicke auf das Symbol, um das Fenster zu öffnen. (In den Einstellungen änderbar.)",
            ["Couldn't start Windows Live Captions automatically. Press Win+Ctrl+L once, or turn it on in Settings > Accessibility > Captions. The first time, Windows may ask to set it up."] = "Die Windows-Live-Untertitel konnten nicht automatisch gestartet werden. Drücke einmal Win+Strg+L oder aktiviere sie unter Einstellungen > Barrierefreiheit > Untertitel. Beim ersten Mal fragt Windows eventuell nach der Einrichtung.",
            ["Discord may show you as playing the Steam game \"Tempo\" because this folder is named Tempo. Rename the folder (e.g. TempoClicker) or reinstall with install.cmd to stop that."] = "Discord zeigt möglicherweise an, dass du das Steam-Spiel „Tempo“ spielst, weil dieser Ordner Tempo heißt. Benenne den Ordner um (z. B. TempoClicker) oder installiere mit install.cmd neu, um das zu verhindern.",
            ["Heads-up: the \"Speaker 1/2\" caption labels are AI guesses from voice pitch and pauses — they make plenty of mistakes. Treat them as a reading aid; turn off in Settings → Live Captions."] = "Hinweis: Die Untertitel-Bezeichnungen „Sprecher 1/2“ sind KI-Schätzungen aus Stimmlage und Pausen – sie liegen oft daneben. Sieh sie als Lesehilfe; abschalten unter Einstellungen → Live-Untertitel.",
            ["Move mode ON: drag the caption bars where you want them, then turn move mode off in the tray to lock them."] = "Verschiebemodus AN: Ziehe die Untertitelleisten dorthin, wo du sie haben möchtest, und schalte den Verschiebemodus im Infobereich wieder aus, um sie zu fixieren.",
            ["Windows Live Captions can't be read on this PC (its accessibility API isn't working), so Tempo switched to its own offline captions."] = "Die Windows-Live-Untertitel können auf diesem PC nicht gelesen werden (die Barrierefreiheits-API funktioniert nicht), daher hat Tempo auf seine eigenen Offline-Untertitel umgeschaltet.",

            ["settings ok"] = "Einstellungen ok",
            ["no speaker found"] = "kein Lautsprecher",
            ["profile"] = "Profil", ["profiles"] = "Profile",
            ["macro"] = "Makro", ["macros"] = "Makros",
            ["hotkey"] = "Tastenkürzel", ["hotkeys"] = "Tastenkürzel",
            ["microphone detected"] = "Mikrofon erkannt",
            ["speaker detected"] = "Lautsprecher erkannt",
            ["set \"Listen to\" to Microphone."] = "stelle „Zuhören“ auf Mikrofon.",
            ["Dim"] = "Abdunkeln",
            ["Bind a key in Keybinds → “Camera-relative movement” to arm it in-game."] = "Belege eine Taste unter Tastenkürzel → „Kamerarelative Bewegung“, um sie im Spiel zu aktivieren.",
            ["Captions are currently using the microphone. Switch to system audio, so videos and games get captioned directly?"] = "Die Untertitel nutzen gerade das Mikrofon. Auf Systemton umschalten, damit Videos und Spiele direkt untertitelt werden?",
            ["Captions can't appear over this game: it uses Exclusive Fullscreen, which no app can draw over."] = "Untertitel können über diesem Spiel nicht erscheinen: Es nutzt exklusiven Vollbildmodus, über den keine App zeichnen kann.",
            ["Details: Settings → Data & Backup → Live debug."] = "Details: Einstellungen → Daten und Sicherung → Live-Diagnose.",
            ["In the game's video settings choose 'Borderless' — it looks the same, and captions will show."] = "Wähle in den Grafikeinstellungen des Spiels „Randlos“ – es sieht gleich aus, und die Untertitel erscheinen.",
            ["Let a 2nd real mouse control it — move, click, right-click to spam (needs 2 mice)"] = "Eine 2. echte Maus steuert ihn – bewegen, klicken, Rechtsklick zum Spammen (benötigt 2 Mäuse)",
            ["Pick the mouse above (auto-detects when you plug one in) or choose \"Ask by wiggling\". Move it to aim the second cursor (your real pointer stays put); left/right = a real click that opens apps & hits anything; middle = start/stop spam. Emergency-Stop halts it."] = "Wähle oben die Maus (wird beim Anschließen automatisch erkannt) oder „Durch Wackeln fragen“. Bewege sie, um den zweiten Cursor zu zielen (dein echter Zeiger bleibt stehen); links/rechts = ein echter Klick, der Apps öffnet und alles trifft; Mitte = Spam starten/stoppen. Der Not-Stopp beendet ihn.",
            ["This PC has no speaker, so Tempo's captions can't hear system audio right now. Use this microphone for captions instead?"] = "Dieser PC hat keinen Lautsprecher, daher können Tempos Untertitel den Systemton gerade nicht hören. Stattdessen dieses Mikrofon verwenden?",
            ["Tip: press Save on the\nClicker tab to store these\npoints in the profile."] = "Tipp: Drücke Speichern im\nKlicker-Tab, um diese Punkte\nim Profil zu sichern.",
            ["Want your own logo? Click \"Choose image…\" and pick a .gif / .png / .jpg, or drag an image straight onto the logo (even from a web page)."] = "Möchtest du dein eigenes Logo? Klicke auf „Bild wählen…“ und nimm eine .gif / .png / .jpg-Datei, oder ziehe ein Bild direkt auf das Logo (auch von einer Webseite).",
            ["While enabled, Tempo intercepts W/A/S/D and sends its own. It cannot read the game's camera — it estimates it from mouse movement, so calibrate below and turn OFF in-game mouse acceleration. Many online games forbid input automation."] = "Solange dies aktiv ist, fängt Tempo W/A/S/D ab und sendet eigene Tasten. Es kann die Kamera des Spiels nicht auslesen – es schätzt sie aus der Mausbewegung, also kalibriere unten und schalte die Mausbeschleunigung im Spiel AUS. Viele Online-Spiele verbieten Eingabeautomatisierung.",
            ["Windows Live Captions started while Tempo's own captions are on. Both are listening to the same audio, so you'll see two bars and pay for two engines. Press Win+Ctrl+L to turn the Windows one off."] = "Die Windows-Live-Untertitel wurden gestartet, während Tempos eigene laufen. Beide hören denselben Ton, du siehst also zwei Leisten und bezahlst zwei Engines. Drücke Win+Strg+L, um die von Windows auszuschalten.",
            ["isn't downloaded yet — click “Download model”."] = "ist noch nicht heruntergeladen – klicke auf „Modell herunterladen“.",

            ["Welcome to Tempo"] = "Willkommen bei Tempo",
            ["Quick safety note"] = "Kurzer Sicherheitshinweis",
            ["Tempo is free and only officially published in two places:"] = "Tempo ist kostenlos und wird offiziell nur an zwei Stellen veröffentlicht:",
            ["If you downloaded this copy anywhere else, it may have been modified by someone other than the developer. You can verify your copy against the SHA-256 checksum published with every official release."] = "Wenn du diese Kopie woanders heruntergeladen hast, wurde sie möglicherweise von jemand anderem als dem Entwickler verändert. Du kannst deine Kopie mit der SHA-256-Prüfsumme abgleichen, die zu jeder offiziellen Version veröffentlicht wird.",
            ["(no device found)"] = "(kein Gerät gefunden)",
            ["0 = instant"] = "0 = sofort",
            ["A clicking, macro and accessibility tool that runs entirely on your PC."] = "Ein Klick-, Makro- und Barrierefreiheitswerkzeug, das vollständig auf deinem PC läuft.",
            ["A macro is being recorded — restarting will discard it."] = "Ein Makro wird aufgezeichnet – ein Neustart verwirft es.",
            ["A macro is playing — restarting will stop it."] = "Ein Makro wird abgespielt – ein Neustart stoppt es.",
            ["A microphone was just connected:"] = "Ein Mikrofon wurde gerade angeschlossen:",
            ["A speaker was just connected:"] = "Ein Lautsprecher wurde gerade angeschlossen:",
            ["AI face && mouth analysis (experimental)"] = "KI-Gesichts- && Mundanalyse (experimentell)",
            ["After mirroring, remove it from the Windows Action Center"] = "Nach dem Spiegeln aus dem Windows-Info-Center entfernen",
            ["All caption settings…"] = "Alle Untertitel-Einstellungen…",
