            ["trace"] = "traccia",
            ["GitHub has no release matching this version number, so nothing outside this PC can confirm the file. That is normal for a build you made yourself — but if you downloaded it, get it from the official releases page instead."] = "Su GitHub non esiste nessuna versione pubblicata con questo numero, quindi niente al di fuori di questo PC può confermare il file. È normale per una build compilata da te, ma se l'hai scaricata prendila dalla pagina ufficiale delle versioni.",
            ["This copy does not match the release published for its version number. Either it was altered after download, or it did not come from the official releases page. Reinstall from there to be sure."] = "Questa copia non corrisponde alla versione pubblicata per il suo numero di versione. O è stata alterata dopo il download, o non proviene dalla pagina ufficiale delle versioni. Reinstalla da lì per esserne certo.",
            ["This version was never published"] = "Questa versione non è mai stata pubblicata",
            ["⚠ No release with this version number exists on GitHub, so nothing outside this PC can confirm the file. Normal for a build you made yourself."] = "⚠ Su GitHub non esiste nessuna versione pubblicata con questo numero, quindi niente al di fuori di questo PC può confermare il file. Normale per una build compilata da te.",
            ["✓ Verified against the release published on GitHub."] = "✓ Verificato con la versione pubblicata su GitHub.",
            ["✗ This copy does not match the release published for its version number. If you did not replace it yourself, reinstall from the official download."] = "✗ Questa copia non corrisponde alla versione pubblicata per il suo numero di versione. Se non l'hai sostituita tu, reinstalla dal download ufficiale.",
            ["Check now"] = "Controlla ora",
            ["Check that Tempo hasn't been tampered with"] = "Controlla che Tempo non sia stato manomesso",
            ["Trust this copy"] = "Considera affidabile",
            ["Could not be checked right now."] = "Non è stato possibile controllare adesso.",
            ["Not checked yet."] = "Non ancora controllato.",
            ["Off — Tempo will not notice if its program file is replaced."] = "Disattivato: Tempo non si accorgerà se il suo file di programma viene sostituito.",
            ["Part of Tempo.exe is unreadable. This usually follows a crash or a power cut during an update. Reinstalling from the official download fixes it."] = "Una parte di Tempo.exe è illeggibile. Di solito succede dopo un crash o un'interruzione di corrente durante un aggiornamento. Reinstallare dal download ufficiale lo risolve.",
            ["Record this copy of Tempo.exe as the one you trust?\n\nOnly do this if you know why the file changed — for example you installed a build yourself. If you did not change it, do not accept it: reinstall from the official download instead."] = "Registrare questa copia di Tempo.exe come quella di cui ti fidi?\n\nFallo solo se sai perché il file è cambiato, per esempio perché hai installato tu una build. Se non l'hai cambiato tu, non accettarla: reinstalla dal download ufficiale.",
            ["Tempo has been modified"] = "Tempo è stato modificato",
            ["Tempo's program file is damaged"] = "Il file di programma di Tempo è danneggiato",
            ["Tempo.exe is not the file that was installed, and the version number has not changed. If you did not replace it yourself, reinstall from the official download."] = "Tempo.exe non è il file che era stato installato e il numero di versione non è cambiato. Se non l'hai sostituito tu, reinstalla dal download ufficiale.",
            ["This copy was packaged by someone else. If you did not build it yourself, replace it with the official download."] = "Questa copia è stata pacchettizzata da qualcun altro. Se non l'hai compilata tu, sostituiscila con il download ufficiale.",
            ["This is not an official Tempo build"] = "Questa non è una build ufficiale di Tempo",
            ["✓ Tempo.exe is the file that was installed."] = "✓ Tempo.exe è il file che era stato installato.",
            ["✗ Tempo.exe has changed since it was installed. If you did not replace it yourself, reinstall from the official download."] = "✗ Tempo.exe è cambiato da quando è stato installato. Se non l'hai sostituito tu, reinstalla dal download ufficiale.",
            ["✗ Tempo.exe is damaged — part of it is unreadable. Reinstalling fixes it."] = "✗ Tempo.exe è danneggiato: una parte è illeggibile. Reinstallarlo lo risolve.",
            ["✗ This copy was packaged by someone else, not the official Tempo build."] = "✗ Questa copia è stata pacchettizzata da qualcun altro, non è Tempo ufficiale.",
            ["This report is too long for your email app to carry — it would arrive cut off part-way through, most likely losing the activity log at the end.\n\nCopy it to the clipboard instead? You can paste the whole thing into a new email."] = "Questo rapporto è troppo lungo per la tua app di posta: arriverebbe troncato a metà e con ogni probabilità perderebbe il registro attività alla fine.\n\nCopiarlo invece negli appunti? Potrai incollarlo per intero in una nuova email.",
            ["Also include Tempo's recent activity log"] = "Includi anche il registro attività recente di Tempo",
            ["Helps a lot, but may mention files you have opened in Tempo — it is added to the text above so you can read it first."] = "Aiuta molto, ma può citare file che hai aperto in Tempo: viene aggiunto al testo qui sopra così puoi leggerlo prima.",
            ["How would you like to send it?"] = "Come vuoi inviarlo?",
            ["Nothing is sent until you choose a way to send it below. Your Windows account name, PC name and personal folders are removed automatically — and this is the whole report, so you can edit or delete anything else before it goes."] = "Non viene inviato nulla finché non scegli qui sotto come inviarlo. Il nome del tuo account Windows, il nome del PC e le tue cartelle personali vengono rimossi automaticamente — e questo è il rapporto completo, quindi puoi modificare o cancellare qualsiasi altra cosa prima che parta.",
            ["Privacy: this includes only Tempo's version, your Windows version and the technical error — never your clicks, settings or files. Your Windows account name and PC name are removed, from the subject line as well as the text. Nothing is sent until you submit. You can edit the text below first."] = "Privacy: qui c'è solo la versione di Tempo, la tua versione di Windows e l'errore tecnico: mai i tuoi clic, le impostazioni o i file. Il nome del tuo account Windows e il nome del PC vengono rimossi, dall'oggetto come dal testo. Non viene inviato nulla finché non lo invii tu. Puoi modificare prima il testo qui sotto.",
            ["There is no activity log to include yet."] = "Non c'è ancora nessun registro attività da includere.",
            ["{0}   ·  last used"] = "{0}   ·  usato l'ultima volta",
            ["GitHub issue"] = "Segnalazione su GitHub",
            ["Gmail (in your browser)"] = "Gmail (nel browser)",
            ["Outlook (in your browser)"] = "Outlook (nel browser)",
            ["Yahoo Mail (in your browser)"] = "Yahoo Mail (nel browser)",
            ["Copy report to clipboard"] = "Copia il rapporto negli appunti",
            ["Append the steps of which macro?"] = "Aggiungere i passi di quale macro?",
            ["°/count"] = "°/conteggio",
            ["Speaker"] = "Parlante",
            ["1 duplicate move"] = "1 spostamento duplicato",
            ["1 empty delay"] = "1 attesa vuota",
            ["1 input is never released"] = "1 input non viene mai rilasciato",
            ["1 problem and 1 suggestion found"] = "1 problema e 1 suggerimento trovati",
            ["1 problem and {1} suggestions found"] = "1 problema e {1} suggerimenti trovati",
            ["1 step clicks off-screen"] = "1 passo clicca fuori dallo schermo",
            ["1 suggestion found — nothing is broken"] = "1 suggerimento trovato — non c'è nulla di rotto",
            ["1 very long pause (longest {1} s)"] = "1 pausa molto lunga (la più lunga {1} s)",
            ["1.  Switch to your game (this window stays on top).\n2.  Hold {0} down.\n3.  While holding it, turn your camera EXACTLY one full circle (360°)\n     — all the way round, back to where it started.\n4.  Release {0}.\n\nCounting only runs while {0} is held, so moving the mouse back here afterwards won't spoil the measurement."] = "1.  Passa al tuo gioco (questa finestra resta in primo piano).\n2.  Tieni premuto {0}.\n3.  Tenendolo premuto, ruota la telecamera ESATTAMENTE di un giro completo (360°)\n     — tutto il giro, fino a tornare al punto di partenza.\n4.  Rilascia {0}.\n\nIl conteggio va avanti solo mentre {0} è premuto, quindi riportare il mouse qui dopo non rovina la misura.",
            ["A real hand never lands twice on the same pixel. The fix scatters them by up to ±{0} px, which stays well inside any button."] = "Una mano vera non cade mai due volte sullo stesso pixel. La riparazione li sparpaglia fino a ±{0} px, il che resta ampiamente dentro qualsiasi pulsante.",
            ["Add Click Point"] = "Aggiungi punto di clic",
            ["Captured {0} steps  ·  ≈{1}"] = "Catturati {0} passi  ·  ≈{1}",
            ["Consecutive moves to the same spot (within {0} px). Recording samples the pointer far faster than anything reacts to it. Removing them shortens the macro without changing what it does."] = "Spostamenti consecutivi nello stesso punto (entro {0} px). La registrazione campiona il puntatore molto più in fretta di quanto qualsiasi cosa vi reagisca. Rimuoverli accorcia la macro senza cambiare quello che fa.",
            ["Downloading…"] = "Download in corso…",
            ["Edit Click Point"] = "Modifica punto di clic",
            ["Enable GPU engine"] = "Attiva il motore GPU",
            ["Esc or your stop key to cancel"] = "Esc o il tuo tasto di stop per annullare",
            ["GPU speech engine enabled"] = "Motore vocale GPU attivato",
            ["GPU speech engine turned off"] = "Motore vocale GPU disattivato",
            ["Gaps this long are usually you reading the screen while recording, not part of the task. The fix caps them at {0} s so the macro doesn't idle."] = "Pause così lunghe di solito sei tu che leggi lo schermo mentre registri, non fanno parte del compito. La riparazione le limita a {0} s perché la macro non resti ferma.",
            ["Get ready…"] = "Preparati…",
            ["Getting the {0} model…"] = "Recupero del modello {0}…",
            ["Hide caption bar"] = "Nascondi la barra dei sottotitoli",
            ["Hide history window"] = "Nascondi la finestra della cronologia",
            ["Identical timing to the millisecond is something no hand produces. The fix varies each gap by up to ±{0}%, keeping the overall pace but removing the metronome."] = "Un ritmo identico al millisecondo non lo produce nessuna mano. La riparazione varia ogni intervallo fino a ±{0}%, mantenendo l'andamento generale ma togliendo il metronomo.",
            ["Input"] = "Immissione",
            ["Not a usable speech model"] = "Non è un modello vocale utilizzabile",
            ["Press {0} to stop"] = "Premi {0} per fermare",
            ["Sorry about that. The details below have been saved. Reporting them helps get it fixed."] = "Ci dispiace. I dettagli qui sotto sono stati salvati. Segnalarli aiuta a correggere il problema.",
            ["Sorry about that. You can keep using Tempo. Reporting the details helps get it fixed."] = "Ci dispiace. Puoi continuare a usare Tempo. Segnalare i dettagli aiuta a correggere il problema.",
            ["Stop captions"] = "Ferma i sottotitoli",
            ["Tempo couldn't read this file."] = "Tempo non è riuscito a leggere questo file.",
            ["Tempo has to close"] = "Tempo deve chiudersi",
            ["Tempo hit an unexpected error"] = "Tempo ha incontrato un errore imprevisto",
            ["The GPU engine can only be selected while Tempo starts up, so captions are still running on the CPU engine until it restarts."] = "Il motore GPU può essere scelto solo all'avvio di Tempo, quindi i sottotitoli continuano a girare sul motore CPU finché non si riavvia.",
            ["The macro presses a button or key and playback ends without letting go, so it stays held afterwards. The fix appends the missing releases at the end."] = "La macro preme un pulsante o un tasto e la riproduzione finisce senza rilasciarlo, quindi resta premuto dopo. La riparazione aggiunge i rilasci mancanti alla fine.",
            ["The speech engine is fixed while Tempo runs, so captions are still using the GPU engine until it restarts."] = "Il motore vocale resta fisso mentre Tempo è in esecuzione, quindi i sottotitoli usano ancora il motore GPU finché non si riavvia.",
            ["These coordinates are outside every monitor you have now — usually a macro recorded on a different display setup. The fix pulls them back onto the nearest screen so they hit something instead of nothing."] = "Queste coordinate sono fuori da ogni monitor che hai adesso: di solito una macro registrata con un'altra configurazione di schermi. La riparazione le riporta sullo schermo più vicino, così colpiscono qualcosa invece di niente.",
            ["This file can't be used"] = "Questo file non si può usare",
            ["Use this speech model?"] = "Usare questo modello vocale?",
            ["Use your stop hotkey to finish"] = "Usa la tua scorciatoia di stop per finire",
            ["Wait steps of zero milliseconds. They cost a step each and wait for nothing."] = "Passi di attesa da zero millisecondi. Costano un passo ciascuno e non aspettano nulla.",
            ["{0}   ▸ press a new combo"] = "{0}   ▸ premi una nuova combinazione",
            ["{0} clicks hit the exact same pixel ({1}, {2})"] = "{0} clic colpiscono esattamente lo stesso pixel ({1}, {2})",
            ["{0} duplicate moves"] = "{0} spostamenti duplicati",
            ["{0} empty delays"] = "{0} attese vuote",
            ["{0} inputs are never released"] = "{0} input non vengono mai rilasciati",
            ["{0} of {1} gaps are exactly {2} ms"] = "{0} intervalli su {1} sono esattamente di {2} ms",
            ["{0} problems and 1 suggestion found"] = "{0} problemi e 1 suggerimento trovati",
            ["{0} problems and {1} suggestions found"] = "{0} problemi e {1} suggerimenti trovati",
            ["{0} steps click off-screen"] = "{0} passi cliccano fuori dallo schermo",
            ["{0} suggestions found — nothing is broken"] = "{0} suggerimenti trovati — non c'è nulla di rotto",
            ["{0} very long pauses (longest {1} s)"] = "{0} pause molto lunghe (la più lunga {1} s)",
            ["▸ listening… press keys / mouse button (Esc to leave)"] = "▸ in ascolto… premi tasti o un pulsante del mouse (Esc per uscire)",
            ["scripts"] = "script",

