            ["A new version of Tempo is available"] = "È disponibile una nuova versione di Tempo",
            ["Accent"] = "Accento",
            ["CSV file (*.csv)|*.csv|All files (*.*)|*.*"] = "File CSV (*.csv)|*.csv|Tutti i file (*.*)|*.*",
            ["Choose a Whisper speech model"] = "Scegli un modello vocale Whisper",
