            ["Images (*.gif;*.png;*.jpg;*.jpeg)|*.gif;*.png;*.jpg;*.jpeg|All files (*.*)|*.*"] = "Immagini (*.gif;*.png;*.jpg;*.jpeg)|*.gif;*.png;*.jpg;*.jpeg|Tutti i file (*.*)|*.*",
            ["Images (*.png;*.gif;*.jpg;*.jpeg;*.bmp)|*.png;*.gif;*.jpg;*.jpeg;*.bmp|All files (*.*)|*.*"] = "Immagini (*.png;*.gif;*.jpg;*.jpeg;*.bmp)|*.png;*.gif;*.jpg;*.jpeg;*.bmp|Tutti i file (*.*)|*.*",
            ["Import settings"] = "Importa impostazioni",
