            ["Rescan"] = "Cerca di nuovo",
            ["Using: {0}"] = "In uso: {0}",
            ["Tempo runs the script with your own Python and waits for it to finish. Held keys and buttons are released first, so nothing stays pressed while it runs."] = "Tempo esegue lo script con il tuo Python e aspetta che finisca. I tasti e i pulsanti tenuti premuti vengono rilasciati prima, così nulla resta premuto durante l'esecuzione.",
            ["Choose a Python script"] = "Scegli uno script Python",
            ["Python script (*.py;*.pyw)|*.py;*.pyw|All files (*.*)|*.*"] = "Script Python (*.py;*.pyw)|*.py;*.pyw|Tutti i file (*.*)|*.*",
            ["Choose a .py file for this step."] = "Scegli un file .py per questo passaggio.",
            ["That file doesn't exist:\n\n{0}"] = "Quel file non esiste:\n\n{0}",
            ["No Python interpreter found on this PC."] = "Nessun interprete Python trovato su questo PC.",
            ["Tempo could not find Python on this PC. Install it from python.org, then use Rescan in the script step."] = "Tempo non ha trovato Python su questo PC. Installalo da python.org, poi usa «Cerca di nuovo» nel passaggio di script.",
            ["Python could not be started."] = "Impossibile avviare Python.",
            ["The script file no longer exists:\n{0}"] = "Il file dello script non esiste più:\n{0}",
            ["The script exited with code {0}."] = "Lo script è terminato con il codice {0}.",
            ["The script was still running after {0} ms and was stopped."] = "Lo script era ancora in esecuzione dopo {0} ms ed è stato fermato.",
            ["The macro was stopped while the script was running."] = "La macro è stata fermata mentre lo script era in esecuzione.",
            ["… {0} more line(s) not shown."] = "… altre {0} riga/righe non mostrate.",
            ["Script step failed: {0}"] = "Passaggio di script fallito: {0}",
            ["Script step failed: {0}\n{1}"] = "Passaggio di script fallito: {0}\n{1}",
            ["{0} script step(s) in \"{1}\" point at a file that isn't there:\n\n{2}\nOpen the macro editor and pick the file again, or delete those steps."] = "{0} passaggio/i di script in «{1}» puntano a un file che non c'è:\n\n{2}\nApri l'editor delle macro e riscegli il file, oppure elimina quei passaggi.",
            ["'{0}' contains {1} step(s) that run a Python script:\n\n{2}\nScripts run as you, with your files and your network. Only keep this macro if you trust where it came from and you have read the script.\n\nImport it anyway?"] = "«{0}» contiene {1} passaggio/i che eseguono uno script Python:\n\n{2}\nGli script vengono eseguiti come te, con i tuoi file e la tua rete. Conserva questa macro solo se ti fidi della sua provenienza e hai letto lo script.\n\nImportarla comunque?",
            ["Tempo's speech models come from the whisper.cpp project on Hugging Face — the same place the \"Download model\" button uses. You only need this page for something Tempo doesn't list, such as a language-specific or fine-tuned model.\n\nOn that page:\n   •  Download any file named ggml-….bin  (ignore everything else)\n   •  \"q5\" / \"q8\" in the name means a smaller, quantised build — same hearing, about a third of the size and CPU\n   •  \".en\" means English-only; without it, the model handles any language\n   •  Bigger is more accurate but slower — large is roughly 3 GB\n\nThen save it into Tempo's models folder and it will be picked up automatically. You can also keep it anywhere you like and use \"Use a model file from anywhere\".\n\nOpen the page in your browser now?"] = "I modelli vocali di Tempo provengono dal progetto whisper.cpp su Hugging Face, la stessa fonte usata dal pulsante \"Scarica il modello\". Questa pagina serve solo per qualcosa che Tempo non elenca, come un modello specifico per una lingua o ottimizzato.\n\nIn quella pagina:\n   •  Scarica un file chiamato ggml-….bin  (ignora tutto il resto)\n   •  \"q5\" / \"q8\" nel nome indica una versione quantizzata più piccola: stessa resa, circa un terzo delle dimensioni e della CPU\n   •  \".en\" significa solo inglese; senza, il modello gestisce qualsiasi lingua\n   •  Più grande è più preciso ma più lento: large occupa circa 3 GB\n\nPoi salvalo nella cartella dei modelli di Tempo e verrà rilevato automaticamente. Puoi anche tenerlo dove preferisci e usare \"Usa un file di modello da qualsiasi posizione\".\n\nAprire ora la pagina nel browser?",
            ["That file could not be read as Tempo settings."] = "Impossibile leggere quel file come impostazioni di Tempo.",
            ["The update check took too long and was cancelled. Please check your connection and try again."] = "Il controllo degli aggiornamenti ha richiesto troppo tempo ed è stato annullato. Verifica la connessione e riprova.",
            ["The update failed its integrity check (checksum mismatch). Please try again, or use the download page."] = "L'aggiornamento non ha superato il controllo di integrità (checksum non corrispondente). Riprova oppure usa la pagina di download.",
            ["There are no macros to export."] = "Non ci sono macro da esportare.",
            ["There are no other macros to merge in."] = "Non ci sono altre macro da unire.",
            ["This macro has no play stats to reset."] = "Questa macro non ha statistiche di riproduzione da azzerare.",
            ["This macro has no steps yet — record or edit it first."] = "Questa macro non ha ancora passaggi: registrala o modificala prima.",
            ["Window position reset."] = "Posizione della finestra ripristinata.",
            ["A macro is still being recorded.\n\nUpdating restarts Tempo, which discards the recording in progress.\n\nYes — discard it and update now\nNo — cancel the update so you can finish and save it"] = "È ancora in corso la registrazione di una macro.\n\nL'aggiornamento riavvia Tempo e scarta la registrazione in corso.\n\nSì: scartala e aggiorna ora\nNo: annulla l'aggiornamento per poterla completare e salvare",
            ["Also delete the Tempo program file itself?\n\nYes — remove everything, including Tempo.exe\nNo — remove data only and keep Tempo.exe\n\nTempo will close to finish removing files."] = "Eliminare anche il file di programma di Tempo?\n\nSì: rimuovi tutto, compreso Tempo.exe\nNo: rimuovi solo i dati e conserva Tempo.exe\n\nTempo si chiuderà per completare la rimozione dei file.",
            ["Back up all your data first?\n\nYes — choose a folder; Tempo copies all profiles, macros, settings\n         and history there before uninstalling\nNo — uninstall without a backup"] = "Fare prima un backup di tutti i tuoi dati?\n\nSì: scegli una cartella; Tempo vi copierà tutti i profili, le macro, le impostazioni\n         e la cronologia prima di disinstallare\nNo: disinstalla senza backup",
            ["A macro with that name already exists."] = "Esiste già una macro con quel nome.",
            ["Add at least one enabled point first."] = "Aggiungi prima almeno un punto attivato.",
            ["Clear the recent-sessions history?"] = "Cancellare la cronologia delle sessioni recenti?",
            ["Clicking is still running. Exit anyway?"] = "I clic sono ancora in corso. Uscire comunque?",
            ["Could not export settings."] = "Impossibile esportare le impostazioni.",
            ["Could not export the macro."] = "Impossibile esportare la macro.",
