            ["No"] = "No",
            ["Its window has been brought to the front."] = "La sua finestra è stata portata in primo piano.",
            ["If you can't see it, look for the Tempo icon in the system tray — bottom-right, near the clock. You may need to click the ^ arrow first."] = "Se non la vedi, cerca l'icona di Tempo nell'area di notifica, in basso a destra vicino all'orologio. Potrebbe essere necessario fare prima clic sulla freccia ^.",
            ["Always on top: ON"] = "Sempre in primo piano: ATTIVO",
            ["Always on top: OFF"] = "Sempre in primo piano: DISATTIVO",
