            ["Press {0} to stop"] = "Pressione {0} para parar",
            ["Sorry about that. The details below have been saved. Reporting them helps get it fixed."] = "Sentimos muito. Os detalhes abaixo foram salvos. Relatá-los ajuda a corrigir.",
            ["Sorry about that. You can keep using Tempo. Reporting the details helps get it fixed."] = "Sentimos muito. Você pode continuar usando o Tempo. Relatar os detalhes ajuda a corrigir.",
            ["Stop captions"] = "Parar as legendas",
